local Jk=Ik and Ik.infinite_resource_rewards and Ik.infinite_resource_rewards.SummerPearls
for Kk,Lk in ipairs(Jk or{})do
if Hk<=(tonumber(Lk.wave_up_to)or 0)then
return tonumber(Lk.reward)or 0
end
end
return 0
end
function db.pearlsFrom(Mk,Nk)
local Ok=0
for Pk=Mk,Nk do
Ok=Ok+db.perWave(Pk)
end
return Ok
end
function db.board()
local Qk=G.core(glc[1553])
local Rk=G.prof()
if not(Qk and Rk)then
return nil
end
local Sk=Qk.get_board(F.UserId)
if not Sk then
return nil
end
local Tk=type(Rk._summer2_hunt_wins)==glc[1375]and Rk._summer2_hunt_wins or{}
local Uk,Vk,Wk=Tk.maps or{},Tk.weathers or{},Rk._summer2_map_board_claimed_lines or{}
local Xk,Yk,Zk=0,0,0
for _k,al in ipairs(Sk)do
if Uk[al]then
Xk=Xk+1
end
end
for bl in pairs(Qk.get_completed_lines(Sk,Uk))do
Yk=Yk+1
end
for cl in pairs(Vk)do
Zk=Zk+1
end
return{core=Qk,board=Sk,maps=Uk,weathers=Vk,claimed=Wk,squares=Xk,lines=Yk,weathersWon=Zk,total= #Qk.LINES,claimable=Qk.get_claimable_lines(Sk,Uk,Wk)}
end
function db.lineGems()
return 2000*H.pearlValue+10*(G.ITEM_VALUE.star_remnant_limited or 25)
end
function db.firstValue(dl,el)
local fl=db.board()
if not fl then
return 0,{}
end
local gl,hl=0,{}
local il=dl and table.find(fl.board,dl)
if il and not fl.maps[dl]then
local jl=0
for kl,ll in ipairs(fl.core.LINES)do
if table.find(ll.cells,il)then
jl=jl+1
end
end
gl=gl+jl*db.lineGems()/fl.core.SIZE
table.insert(hl,glc[1554])
end
if el and el~=glc[1555]and not fl.weathers[el]then
gl=gl+(1000+5000*H.pearlValue+50*(G.ITEM_VALUE.star_remnant_limited or 25))/db.WEATHERS
table.insert(hl,glc[1556])
end
if not next(fl.maps)then
gl=gl+500+4500*H.pearlValue+200
table.insert(hl,glc[1557])
end
return gl,hl
end
function db.row(ml)
local nl=I.live.event
local ol=I.simRes[glc[1558]..tostring(nl.level)]
local pl=ol and(ol.won and 50 or tonumber(ol.wave))or 50
local ql=ml.runs>0 and ml.coins/ml.runs or db.pearlsFrom(1,pl)*db.MULT_GUESS
local rl,sl=db.firstValue(nl.map,nl.weather)
local tl=G.data(glc[1559])or{}
return{key=glc[1558]..tostring(nl.level),kind=glc[1392],level=nl.level,diff=glc[1560],value=ql*H.pearlValue+rl,coins=ql,p0=0.5,label=glc[1561],why=string.format(glc[1562],math.floor(ql),nl.weather and tl[nl.weather]and(glc[1563]..tl[nl.weather].name)or glc[304],#sl>0 and(glc[1564]..table.concat(sl,glc[1470]))or glc[304])}
end
function db.floor()
return tonumber(I.hunt.pmin)or 1
end
function db.claim()
local ul=db.board()
if not(ul and#ul.claimable>0)then
return
end
local vl=j.request(glc[1565],glc[1566])
if vl then
j.log(1,glc[1567],string.format(glc[1568],#ul.claimable,#ul.claimable==1 and glc[304]or glc[1223]))
end
end
function db.write(wl,xl)
local yl=G.FOLDER..glc[1569]..wl
local zl,Al=pcall(readfile,yl)
pcall(writefile,yl,(zl and type(Al)==glc[1377]and Al or glc[304])..xl..glc[1386])
end
function db.plain(Bl,Cl)
Cl=Cl or 0
if type(Bl)==glc[1375]then
if Cl>5 then
return glc[1570]
end
local Dl={}
for El,Fl in pairs(Bl)do
Dl[tostring(El)]=db.plain(Fl,Cl+1)
end
return Dl
end
if type(Bl)==glc[1376]or type(Bl)==glc[1377]or type(Bl)==glc[1378]then
return Bl
end
return tostring(Bl)
end
function db.shopLook()
local Gl,Hl=j.request(glc[1571],glc[1572])
if Gl and type(Hl)==glc[1375]then
local Il,Jl=pcall(E.JSONEncode,E,Hl)
if Il then
pcall(writefile,G.FOLDER..glc[1573],os.date(glc[1574])..Jl)
end
end
local Kl,Ll=j.request(glc[1575],glc[1576])
if Kl and type(Ll)==glc[1375]and type(Ll[db.ID])==glc[1375]then
local Ml={}
for Nl,Ol in pairs(Ll[db.ID])do
if Nl~=glc[1577]then
Ml[Nl]=Ol
end
end
local Pl,Ql=pcall(E.JSONEncode,E,Ml)
if Pl then
pcall(writefile,G.FOLDER..glc[1578],os.date(glc[1574])..Ql)
end
end
end
function db.weatherStrength(Rl)
local Sl=db.fx(Rl)
local Tl=Sl.dmg/Sl.cd/Sl.hp/Sl.speed*(1+(Sl.range-1)/2)
for Ul,Vl in pairs(Sl.kinds)do
Tl=Tl*(1+P.rogueShare(Ul)*Vl)
end
if Sl.ice>0 then
local Wl=P.rogueShare(glc[1550])
Tl=Tl*(Wl+(1-Wl)/(1-Sl.ice+Sl.ice/V.modFactor(glc[1579])))
end
if Sl.fly>0 then
Tl=Tl*(1-Sl.fly*0.5)
end
if Sl.noCC then
Tl=Tl*0.95
end
if Sl.shroud then
Tl=Tl*0.9
end
return Tl
end
function db.cardGems(Xl,Yl)
local Zl=0
local am=db.pearlsFrom(Yl+1,50)
for bm,cm in pairs(type(Xl.effects)==glc[1375]and Xl.effects or{})do
if type(cm)==glc[1375]then
local dm=tonumber(cm.amount)or 0
if cm.type==glc[1580]then
Zl=Zl+math.abs(dm)*am*H.pearlValue
elseif cm.type==glc[1581]then
local em,fm=pcall(N.rewardValue,cm.reward)
if em then
Zl=Zl+(tonumber(fm)or 0)
end
elseif cm.type==glc[1582]then
Zl=Zl+dm*db.STARFALL_GEMS
elseif cm.type==glc[1583]then
Zl=Zl+dm*100
end
end
end
if Xl.option_type==glc[1584]then
Zl=Zl+db.HARD_GEMS
end
if Xl.weather then
local hm=Xl.weather~=db.weatherNow()
if hm and Xl.weather==glc[1585]then
Zl=Zl+db.STARFALL_GEMS
end
local im=db.board()
if hm and im and Xl.weather~=glc[1555]and not im.weathers[Xl.weather]then
Zl=Zl+(1000+5000*H.pearlValue+50*(G.ITEM_VALUE.star_remnant_limited or 25))/db.WEATHERS
end
end
return Zl
end
function db.text()
local jm=I.live.event
if not(jm and db.is(jm.level))then
return glc[1586]
end
local km,lm=G.data(glc[1559])or{},G.data(glc[1587])or{}
local mm={}
local function nm(om)
return om and lm[om]and lm[om].name or om or glc[1588]
end
table.insert(mm,string.format(glc[1589],nm(jm.map),jm.weather and km[jm.weather]and km[jm.weather].name or glc[1590]))
if type(jm.forecast)==glc[1375]then
table.insert(mm,string.format(glc[1591],jm.forecast.map and nm(jm.forecast.map)or(jm.forecast.map_hint or glc[1592]),jm.forecast.weather and km[jm.forecast.weather]and km[jm.forecast.weather].name or(jm.forecast.weather_hint or glc[1593])))
end
local pm=N.rec(glc[1558]..tostring(jm.level))
if pm.runs>0 then
table.insert(mm,string.format(glc[1594],pm.runs,pm.wins,math.floor(pm.coins/pm.runs)))
else
table.insert(mm,string.format(glc[1595],math.floor(db.pearlsFrom(1,50)*db.MULT_GUESS)))
end
local qm=db.board()
if qm then
table.insert(mm,string.format(glc[1596],qm.squares,#qm.board,qm.lines,qm.total,qm.weathersWon,db.WEATHERS))
end
table.insert(mm,string.format(glc[1597],L.fmt(tonumber(G.cur(glc[1598]))or 0)))
return table.concat(mm,glc[1386])
end
db.SKIN_SET,db.STAR=glc[1599],glc[1600]
db.SKIN_PRICE={Rare=10,Epic=40,Legendary=75,Mythic=300}
db.SKIN_DROP={Rare=0.02,Epic=0.05,Legendary=0.25,Mythic=0.4}
db.STAR_COST=150
function db.skinSet(rm)
local sm=type(rm)==glc[1375]and rm.id
return(sm==db.ID or sm==glc[1601]or(type(rm)==glc[1375]and rm.portal_group==glc[1599]))and db.SKIN_SET or nil
end
function db.skinFits(tm,um)
local vm=G.Units[tm]
local wm=vm and vm.evolved and vm.evolved.from or tm
return um.for_unit==tm or um.for_unit==wm or(um.for_units~=nil and(um.for_units[tm]or um.for_units[wm])and true)or false
end
function db.team()
local xm=I.simTeam and I.simTeam[glc[1558]..tostring(db.ID)]
local ym=G.session()
local zm={}
for Am,Bm in ipairs(xm and xm.uuids or I.savedTeam or{})do
local Cm=ym.collection:get_unit_by_uuid(Bm)
if Cm then
table.insert(zm,Cm)
end
end
return zm
end
function db.skinPlan()
local Dm,Em=G.session(),G.prof()
local Fm=G.data(glc[1510])or{}
local Gm=(Em.inventory and Em.inventory.unique_items)or Em.unique_items or{}
local Hm,Im={},{kinds={},sell={},wear={},pearls=0,missing={}}
for Jm,Km in pairs(Gm)do
local Lm=type(Km)==glc[1375]and G.Items[Km.item_id]
if Lm and Lm.item_group==glc[1510]and Lm._skin_set==db.SKIN_SET and Lm.usage and Fm[Lm.usage.skin_id]then
local Mm=Hm[Km.item_id]
if not Mm then
Mm={id=Km.item_id,name=Lm.name,rarity=Lm.rarity,skinId=Lm.usage.skin_id,skin=Fm[Lm.usage.skin_id],uuids={}}
Hm[Km.item_id]=Mm
table.insert(Im.kinds,Mm)
end
table.insert(Mm.uuids,Km.uuid or Jm)
end
end
table.sort(Im.kinds,function(Nm,Om)
return Nm.name<Om.name
end)
local Pm=db.team()
local Qm=Dm.profile_data.collection.owned_units
for Rm,Sm in ipairs(Im.kinds)do
for Tm,Um in pairs(Qm)do
if db.skinFits(Um.unit_id,Sm.skin)then
Sm.fits=true
break
end
end
local Vm=Sm.rarity==glc[1602]or Sm.rarity==glc[1603]
Sm.keep=(Sm.fits or Vm)and 1 or 0
for Wm=Sm.keep+1,#Sm.uuids do
table.insert(Im.sell,{uuid=Sm.uuids[Wm],name=Sm.name,pearls=db.SKIN_PRICE[Sm.rarity]or 0})
Im.pearls=Im.pearls+(db.SKIN_PRICE[Sm.rarity]or 0)
end
end
for Xm,Ym in ipairs(Pm)do
local Zm=Ym.skin and Ym.skin._skin_id and Fm[Ym.skin._skin_id]
if not(Zm and Zm._skin_set==db.SKIN_SET)then
for _m,an in pairs(Fm)do
if type(an)==glc[1375]and an._skin_set==db.SKIN_SET and db.skinFits(Ym.unit_id,an)then
local bn=_m..glc[1604]
if Hm[bn]then
table.insert(Im.wear,{uuid=Hm[bn].uuids[1],unit=Ym.uuid,unitName=M.name(Ym.unit_id),name=Hm[bn].name})
else
table.insert(Im.missing,{item=bn,unitName=M.name(Ym.unit_id),name=an.name,boost=tonumber(an._damage_boost)or 0,drop=db.SKIN_DROP[an._skin_rarity]or 0})
end
end
end
end
end
return Im
end
function db.starPlan(cn)
cn=cn or db.skinPlan()
local dn=G.Items[db.STAR]or{}
local en=tonumber(dn._mythic_unit_pity)or 400
local fn=(G.prof().capsule_pity_data or{})[db.STAR]or{}
local gn=tonumber(fn.opens_since_mythic_unit)or 0
local hn={opened=tonumber(fn.total_opens)or 0,left=math.max(1,en-gn),units={}}
local jn=tonumber(G.cur(glc[1598]))or 0
hn.can=math.max(0,math.floor((jn-(tonumber(H.pearlFloor)or 0))/db.STAR_COST))
local kn={}
for ln,mn in pairs(G.session().profile_data.collection.owned_units)do
kn[mn.unit_id]=true
local nn=G.Units[mn.unit_id]
if nn and nn.evolved and nn.evolved.from then
kn[nn.evolved.from]=true
end
end
for pn,qn in pairs(dn.usage and dn.usage.possible_rewards or{})do
local rn=qn.unit or qn.item
if rn and G.Units[rn]and G.Units[rn].rarity==glc[1603]and not kn[rn]then
table.insert(hn.units,M.name(rn))
end
end
table.sort(hn.units)
local sn={}
if#cn.missing>0 then
local tn=cn.missing[1]
table.insert(sn,string.format(glc[1605],tn.name,tn.unitName))
end
if#hn.units>0 then
table.insert(sn,string.format(glc[1606],table.concat(hn.units,glc[1470])))
end
hn.why=table.concat(sn,glc[1607])
hn.open= #sn>0 and math.min(hn.can,#hn.units>0 and hn.left or 100)or 0
return hn
end
function db.skinText()
local un,vn=pcall(db.skinPlan)
if not un then
return glc[1608]..tostring(vn)
end
local wn={}
local xn={}
for yn,zn in ipairs(vn.kinds)do
table.insert(xn,string.format(glc[1609],zn.name,#zn.uuids>1 and(glc[1610].. #zn.uuids)or glc[304],(tonumber(zn.skin._damage_boost)or 0)*100,zn.fits and glc[304]or glc[1611]))
end
table.insert(wn,glc[1612]..(#xn>0 and table.concat(xn,glc[1470])or glc[1613])..glc[1614])
if#vn.wear>0 then
local An={}
for Bn,Cn in ipairs(vn.wear)do
table.insert(An,Cn.name..glc[1615]..Cn.unitName)
end
table.insert(wn,glc[1616]..table.concat(An,glc[1470])..glc[1614])
end
for Dn,En in ipairs(vn.missing)do
table.insert(wn,string.format(glc[1617],En.name,En.unitName,En.boost*100,En.drop*100))
end
if#vn.sell>0 then
local Fn={}
for Gn,Hn in ipairs(vn.sell)do
Fn[Hn.name]=(Fn[Hn.name]or 0)+1
end
local In={}
for Jn,Kn in pairs(Fn)do
table.insert(In,Kn..glc[1618]..Jn)
end
table.sort(In)
table.insert(wn,string.format(glc[1619],table.concat(In,glc[1470]),L.fmt(vn.pearls)))
else
table.insert(wn,glc[1620])
end
local Ln,Mn=pcall(db.starPlan,vn)
if Ln then
table.insert(wn,string.format(glc[1621],Mn.opened,Mn.left,L.fmt(Mn.left*db.STAR_COST)))
if Mn.open>0 then
table.insert(wn,string.format(glc[1622],Mn.open,L.fmt(Mn.open*db.STAR_COST),Mn.why,L.fmt(H.pearlFloor)))
elseif Mn.why~=glc[304]then
table.insert(wn,string.format(glc[1623],Mn.why,L.fmt(H.pearlFloor)))
else
table.insert(wn,glc[1624])
end
end
if O.pickNote.skins then
table.insert(wn,O.pickNote.skins)
end
return table.concat(wn,glc[1386])
end
function db.skinTick()
if not(H.skinSmart or H.starOpen)or not(I.live.event and db.is(I.live.event.level))then
return
end
if(j.req.back.skins or 0)>L.now()then
return
end
local Nn=G.session()
local function On(Pn,Qn,Rn)
local Sn=j.gameSaid(Qn)
O.pickNote.skins=string.format(glc[1625],Pn,tostring(Sn or Rn or glc[1626]))
j.log(1,glc[1567],O.pickNote.skins)
j.backoff(glc[1627],1800)
end
local Tn=db.skinPlan()
if H.skinSmart then
local Un=Tn.wear[1]
if Un and(j.req.back.skinWear or 0)<=L.now()then
local Vn=cb.slotOf(Un.unit)
if Vn then
I.str.reequip={uuid=Un.unit,slot=Vn}
j.saveNow()
j.request(glc[1628],glc[1629],Un.unit)
local Wn=L.now()
while L.now()-Wn<4 and cb.slotOf(Un.unit)do
task.wait(0.25)
end
end
local Xn=L.now()
local Yn,Zn=j.request(glc[1630],glc[1631],Un.uuid,{unit_uuid=Un.unit})
local function ao()
local bo=Nn.collection:get_unit_by_uuid(Un.unit)
return bo and bo.skin~=nil
end
while L.now()-Xn<5 and not ao()do
task.wait(0.25)
end
if Vn then
cb.reequip()
end
if ao()then
j.log(1,glc[1567],string.format(glc[1632],Un.name,Un.unitName))
O.pickNote.skins=nil
Tn=db.skinPlan()
else
local co=j.gameSaid(Xn)
O.pickNote.skins=string.format(glc[1633],Un.name,tostring(co or Zn or glc[1626]))
j.log(1,glc[1567],O.pickNote.skins)
j.backoff(glc[1630],1800)
end
end
if#Tn.sell>0 then
local eo,fo={},0
for go=1,math.min(50,#Tn.sell)do
table.insert(eo,Tn.sell[go].uuid)
fo=fo+Tn.sell[go].pearls
end
local ho=tonumber(G.cur(glc[1598]))or 0
local io=L.now()
local jo,ko=j.request(glc[1634],glc[1635],eo)
while L.now()-io<5 and(tonumber(G.cur(glc[1598]))or 0)<=ho do
task.wait(0.25)
end
local mo=(tonumber(G.cur(glc[1598]))or 0)-ho
if mo<=0 then
return On(glc[1636],io,ko)
end
Q.add(string.format(glc[1637],#eo),#eo,glc[1627],string.format(glc[1638],L.fmt(mo)))
O.pickNote.skins=nil
end
end
if H.starOpen then
local no=Nn.inventory
local function oo()
local po,qo=pcall(no.get_number_of_owned_item,no,db.STAR)
return po and tonumber(qo)or 0
end
local ro=L.now()
for so=1,8 do
if L.now()-ro>15 or not j.alive or j.where~=glc[1442]then
break
end
local uo=oo()
local vo=db.starPlan(db.skinPlan())
local wo=L.now()
if uo>0 then
local xo,yo=j.request(glc[1639],glc[1640],db.STAR,{use10=uo>=10,use_all=false})
while L.now()-wo<6 and oo()>=uo do
task.wait(0.25)
end
if oo()>=uo then
return On(glc[1641],wo,yo)
end
j.log(1,glc[1567],string.format(glc[1642],uo-oo(),(tonumber(((G.prof().capsule_pity_data or{})[db.STAR]or{}).total_opens)or 0)))
O.pickNote.skins=nil
elseif vo.open>0 then
local zo=vo.open>=10 and 10 or 1
local Ao=tonumber(G.cur(glc[1598]))or 0
local Bo,Co=j.request(glc[1643],glc[1644],db.STAR,glc[1392],glc[1645],tostring(zo))
while L.now()-wo<5 and oo()<=0 do
task.wait(0.25)
end
if oo()<=0 then
return On(glc[1646],wo,Co)
end
Q.add(string.format(glc[1647],oo()),Ao-(tonumber(G.cur(glc[1598]))or 0),glc[1648],glc[1649]..vo.why)
O.pickNote.skins=nil
else
break
end
end
end
end
function N.list()
local Do=G.prof()
if not Do then
return{}
end
local Eo=Do.level_data
local Fo={}
local Go=os.time()
local function Ho(Io)
Io.rec=N.rec(Io.key)
if(Io.rec.restUntil or 0)>Go or not N.allowed(Io)then
return
end
Io.mod=Io.mod or N.levelMod(Io.level)
if(Io.kind==glc[1526]or Io.kind==glc[1389])and not(Io.kind==glc[1526]and H.dailyLoop)then
local Jo,Ko=N.chOk(Io)
N.skipped[Io.key]=not Jo and(Io.label..glc[1650]..Ko)or nil
if not Jo then
return
end
end
table.insert(Fo,Io)
end
local Lo=I.live or{}
if(H.dailyChallenge or H.onlyChallenges or H.dailyLoop)and Lo.daily and Lo.daily.uuid and Lo.daily.uuid~=Do.last_completed_daily_challenge_uuid and Lo.daily.uuid~=Lo.daily.doneUuid and((Lo.daily.lost or 0)<2 or H.dailyLoop)then
Ho({key=glc[1651],kind=glc[1526],level=glc[1652],diff=glc[1560],value=Lo.daily.value or 300,label=glc[1653],why=string.format(glc[1654],L.fmt(Lo.daily.value or 0)),mod=Lo.daily.mod})
end
if(H.challenge or H.onlyChallenges)and Lo.normal and Lo.normal.uuid and Lo.normal.uuid~=Do.last_completed_challenge_uuid and Lo.normal.uuid~=Lo.normal.doneUuid and(Lo.normal.expires or 0)>Go+360 and(Lo.normal.lost or 0)<2 then
Ho({key=glc[1655],kind=glc[1389],level=Lo.normal.level,diff=glc[1560],value=Lo.normal.value or 100,label=glc[1656]..N.levelName(Lo.normal.level),why=glc[1657],challenge=Lo.normal.challenge})
end
local Mo=L.list(G.WLO.WORLD_ORDER)
local No=H.pickStory or glc[304]
local function Oo(Po,Qo,Ro,So)
if not N.done(Eo,Po,Qo)then
