local Yv={id=Uv,to=Xv,coins=G.cur(glc[1753]),itemCost=0,needCoins=0}
for Zv,_v in pairs(Wv.evolve and Wv.evolve.normal and Wv.evolve.normal.item_requirement or{})do
local aw=G.SaleEvent[_v.item_id]
if aw and type(aw.resource_cost)==glc[1375]and aw.resource_cost.id==glc[1753]then
