local Cx=V.info(V.slim and V.slim(Bx)or Bx,glc[1791]..yx)
local Dx=false
for Ex,Fx in pairs(Cx.configs or{})do
if xx[Ex]or(type(Fx)==glc[1375]and xx[Fx.unit_id or glc[304]])then
Dx=true
break
end
end
if not Dx then
