end
Yx=Yx+hy*math.min(1,gy/fy)
Zx=string.format(glc[1793],tostring(cy.quest_name),L.fmt(ey-fy),L.fmt(ey),L.fmt(math.min(gy,fy)))
end
end
end
end
return Yx,Zx
end
