end
return cb.RELIC_MOVE_GAIN
end
function cb.relicWorth(hD,iD)
local jD=iD._unique_item_data and iD._unique_item_data._unique_relic_data
if not jD then
return 0
end
local kD=G.Items[iD.item_id]or{}
local lD,mD=M.types(hD.unit_id)
if kD.main_damage_type and kD.main_damage_type~=glc[1840]and kD.main_damage_type~=mD then
return 0
end
local nD,oD=0,0
for pD,qD in pairs(jD._core_damage_type_buffs or{})do
if lD[qD.damage_type]then
nD=nD+(tonumber(qD.mul)or 0)+(tonumber(qD.add_upg)or 0)*0.01+(tonumber(qD.pen)or 0)*0.001
oD=oD+(tonumber(qD.crit)or 0)
end
end
nD=nD+oD*0.5
local rD=M.rows(hD.unit_id)
local sD=rD and rD[rD.max]
local tD=(sD and tonumber(sD.cd)or 0)*M.mult(hD,glc[1509])
for uD,vD in pairs(jD._unique_relic_effects or{})do
local wD=type(vD.params)==glc[1375]and vD.params or{}
if vD.id==glc[1841]then
local xD=math.min(1,(tonumber(wD.extra_damage)or 0)*tD/math.max(1,tonumber(wD.time_interval)or 40))
local yD=M.DRONES and M.DRONES[hD.unit_id]
if yD and yD.late and tD>0 then
local zD=1/tD
xD=xD*zD/(zD+(tonumber(yD.max)or 0)*(tonumber(yD.late.dmg)or 0)*(tonumber(yD.hits)or 1)/math.max(0.1,tonumber(yD.late.cd)or 4))
end
nD=nD+xD
elseif vD.id==glc[1842]then
nD=nD+(tonumber(wD.dmg_buff)or 0)*0.25
elseif vD.id==glc[1843]then
nD=nD+(tonumber(wD.dmg_buff)or 0)*oD
elseif vD.id==glc[1844]then
if lD.magic then
nD=0
else
nD=nD+(tonumber(wD.dmg_buff)or 0)*0.3
end
elseif vD.id==glc[1845]then
if lD.water_damage then
nD=nD+0.05
end
end
end
return nD
end
function cb.relicPlan()
local AD=G.session()
if not AD then
return nil
end
local BD=AD.inventory and AD.inventory.inventory_profile_data or{}
local CD={}
for DD,ED in ipairs(BD.unique_items or{})do
if type(ED)==glc[1375]and ED.uuid and(G.Items[ED.item_id]or{}).item_group==glc[1846]then
table.insert(CD,ED)
end
end
local FD={}
for GD,HD in ipairs(M.equipped())do
local JD=HD.data and HD.data.rarity
if not M.isFarm(HD.id)and(JD==glc[1602]or JD==glc[1603]or JD==glc[1824]or JD==glc[1847])then
local KD=cb.share(HD.id)
if not I.str.share[HD.id]then
KD=math.min(KD,0.15)
end
local LD={}
for MD,ND in ipairs(CD)do
local OD=cb.relicWorth(HD.u,ND)*KD*100
if OD>0.01 then
table.insert(LD,{it=ND,w=OD})
end
end
table.sort(LD,function(PD,QD)
if PD.w~=QD.w then
return PD.w>QD.w
end
return PD.it.uuid<QD.it.uuid
end)
local RD,SD={},{}
for TD,UD in ipairs(LD)do
local VD=SD[UD.it.item_id]or 0
if#RD<6 and VD<((G.Items[UD.it.item_id]or{}).unique_equip and 1 or 2)then
SD[UD.it.item_id]=VD+1
table.insert(RD,UD)
end
end
if HD.u._equipped_relic then
local WD=false
for XD,YD in ipairs(RD)do
if YD.it.uuid==HD.u._equipped_relic then
WD=true
end
end
local ZD=not WD and AD.inventory:get_item_by_uuid(HD.u._equipped_relic)
if ZD then
table.insert(RD,{it=ZD,w=cb.relicWorth(HD.u,ZD)*KD*100})
end
end
table.insert(FD,{e=HD,share=KD,opts=RD})
end
end
local _D,aE={},-1
local bE,cE,dE={},{},{}
local function eE(fE,gE)
if fE> #FD then
if gE>aE then
aE=gE
_D=table.clone(bE)
end
return
end
local hE=FD[fE]
bE[hE.e.uuid]=nil
eE(fE+1,gE)
for iE,jE in ipairs(hE.opts)do
local kE=(G.Items[jE.it.item_id]or{}).unique_equip
if not cE[jE.it.uuid]and not(kE and dE[jE.it.item_id])then
cE[jE.it.uuid]=true
if kE then
dE[jE.it.item_id]=true
end
bE[hE.e.uuid]=jE.it.uuid
eE(fE+1,gE+jE.w+(jE.it.uuid==hE.e.u._equipped_relic and 0.01 or 0))
bE[hE.e.uuid]=nil
cE[jE.it.uuid]=nil
if kE then
dE[jE.it.item_id]=nil
end
end
end
end
eE(1,0)
local lE,mE=0,{}
for nE,oE in ipairs(FD)do
local pE=oE.e.u._equipped_relic and AD.inventory:get_item_by_uuid(oE.e.u._equipped_relic)
local qE=pE and cb.relicWorth(oE.e.u,pE)*oE.share*100 or 0
lE=lE+qE
local rE=_D[oE.e.uuid]and AD.inventory:get_item_by_uuid(_D[oE.e.uuid])
local sE=rE and cb.relicWorth(oE.e.u,rE)*oE.share*100 or 0
table.insert(mE,string.format(glc[1848],M.name(oE.e.id),pE and(G.Items[pE.item_id]or{}).name or glc[1613],qE,rE and(G.Items[rE.item_id]or{}).name or glc[1613],sE))
end
return _D,aE-lE,mE,FD
end
function cb.relicsApply(tE)
