end
task.wait(1.2)
if WE.e.u._equipped_relic~=XE then
j.log(1,glc[1830],string.format(glc[1854],(G.Items[(zE.inventory:get_item_by_uuid(XE)or{}).item_id]or{}).name or glc[1855],M.name(WE.e.id),FE(eF)))
j.backoff(glc[1850],300)
I.str.relicAt=0
