table.insert(gF,{id=iF,n=tonumber(jF),xp=tonumber(kF.usage.xp_amount)or 0})
end
end
table.sort(gF,function(lF,mF)
return lF.xp>mF.xp
end)
return gF
end
function cb.xpRoom()
