function cb.run(HG)
local IG=G.session()
local JG=IG and IG.collection:get_unit_by_uuid(HG.uuid)
if not JG then
return
end
if HG.kind==glc[1859]then
local KG=M.trait(JG)
local LG=KG==glc[1868]and 1.5 or 1
local MG=math.max(0,cb.xpFor(JG.unit_id,cb.cap(JG))-(tonumber(JG.xp)or 0))
local NG,OG,PG={},0,0
for QG,RG in ipairs(cb.foodHeld())do
local SG=RG.xp*LG
local TG=math.min(RG.n,math.floor((MG-OG)/math.max(1,SG)))
if TG>0 then
NG[RG.id]=TG
OG=OG+TG*SG
PG=PG+TG
end
end
if PG==0 then
I.str.feedNote=HG.name..glc[1869]
return
end
local UG,VG=tonumber(JG.xp)or 0,cb.level(JG)
local WG,XG=j.request(glc[1859],glc[1870],HG.uuid,NG)
local YG=L.now()
while L.now()-YG<4 and(tonumber((IG.collection:get_unit_by_uuid(HG.uuid)or JG).xp)or 0)<=UG do
task.wait(0.25)
end
local ZG=IG.collection:get_unit_by_uuid(HG.uuid)or JG
local aH=(tonumber(ZG.xp)or 0)-UG
if aH>0 then
Q.add(string.format(glc[1871],PG,HG.name),PG,glc[1872],string.format(glc[1873],L.fmt(aH),VG,cb.level(ZG)))
cb.note(string.format(glc[1874],HG.name,PG,L.fmt(aH),VG,cb.level(ZG),math.abs(aH-OG)>OG*0.1 and string.format(glc[1875],L.fmt(OG))or glc[304]))
else
cb.note(string.format(glc[1876],HG.name,tostring(WG and XG or glc[1626])))
j.backoff(glc[1859],600)
end
elseif HG.kind==glc[1864]then
O.fuseInto(HG.uuid,false)
end
end
function cb.slotOf(bH)
local cH=G.session()
for dH,eH in pairs(cH and cH.profile_data.collection.equipped_units or{})do
