for iH=1,3 do
if cb.slotOf(fH.uuid)then
break
end
j.request(glc[1877],glc[1878],fH.uuid)
local jH=L.now()
while L.now()-jH<3 and not cb.slotOf(fH.uuid)do
task.wait(0.25)
end
end
N._sigAt=nil
if cb.slotOf(fH.uuid)then
I.str.reequip=nil
j.saveSoon()
return true
end
j.log(1,glc[1879],string.format(glc[1880],M.name(hH.unit_id),tostring(fH.slot)))
return false
end
