if not nH.blocked and not(oH and L.now()<oH)and(tonumber(I.str.noWork[nH.kind])or 0)<=lH and(tonumber(I.str.noWork[nH.kind..glc[1485]..tostring(nH.uuid)])or 0)<=lH then
