function cb.hasWork(xH)
if not xH then
local yH=cb.focusReady()
if yH then
return glc[1881]..M.name(yH.from)..glc[1882],glc[1756]
end
if O.snipeWanted()then
return glc[1883]..M.name(H.snipeUnit)..glc[1884],glc[1885]
end
if O.snipeDue()then
return glc[1886]..M.name(H.snipeUnit)..glc[1887],glc[1885]
end
if I.ownSwap then
return glc[1888]..M.name(I.ownSwap.into)..glc[1889],glc[1890]
end
end
if not H.team or H.strDry then
return nil
end
cb.acts=cb.plan()
O.last.teamPlan=L.now()
local zH=cb.acts
if not xH then
zH={}
for AH,BH in ipairs(cb.acts)do
if not(BH.kind==glc[1859]and(tonumber(BH.gain)or 0)<cb.FEED_STOP_GAIN)then
table.insert(zH,BH)
end
end
end
local CH=cb.nextAct(zH)
if CH then
return CH.text,CH.kind
end
if H.teamRelics and(tonumber(I.str.noWork.relic)or 0)<=os.time()and(not xH or not(H.autoTeam and H.play))then
local DH,EH=cb.relicPlan()
if EH and EH>=(xH and cb.relicBar()or cb.RELIC_SETTLED_GAIN)then
return string.format(glc[1891],EH),glc[1892]
