local mY=I.portalPay[kY]or{n=0}
mY.n=(tonumber(mY.n)or 0)+1
mY.per=mY.per and(mY.per+(lY-mY.per)*math.max(0.25,1/mY.n))or lY
I.portalPay[kY]=mY
end
local nY,oY=(G.Items[gY.item]or{}).name or gY.item,(G.Items[gY.portal]or{}).name or gY.portal
if gY.used then
O.portalLine(string.format(glc[2279],os.date(glc[2280]),hY,nY,W.have(gY.item),iY))
if gY.won==false then
j.log(1,glc[2269],string.format(glc[2281],N.levelName(N.PORTALS[gY.portal].level),hY,nY,W.have(gY.item),iY))
else
jY(gY.portal,math.max(0,hY))
