jY(glc[1790]..gY.portal,math.max(0,pY))
j.log(1,glc[2269],string.format(glc[2283],N.levelName(N.PORTALS[gY.portal].from),pY,oY,iY,hY>0 and string.format(glc[2284],hY,nY)or glc[304]))
