for vY,wY in ipairs(I.savedTeam or{})do
uY[wY]=true
end
local xY={}
for yY,zY in ipairs(sY)do
local AY=tY.collection:get_unit_by_uuid(zY)
local BY=AY and AY._equipped_relic and tY.inventory:get_item_by_uuid(AY._equipped_relic)
if BY and BY.item_id and(G.Items[BY.item_id]or{}).unique_equip then
table.insert(xY,{uuid=zY,u=AY,kind=BY.item_id,relic=AY._equipped_relic,k=(uY[zY]and 1e12 or 0)+cb.score(AY)})
end
end
table.sort(xY,function(CY,DY)
if CY.k~=DY.k then
return CY.k>DY.k
end
return CY.uuid<DY.uuid
end)
local EY={}
for FY,GY in ipairs(xY)do
if EY[GY.kind]then
local HY=(G.Items[GY.kind]or{}).name or GY.kind
local IY,JY=j.request(glc[2285],glc[1851],GY.relic)
local KY=L.now()
while L.now()-KY<3 and GY.u._equipped_relic==GY.relic do
