end
if GY.u._equipped_relic~=GY.relic then
I.relicOff[GY.uuid]=GY.relic
j.log(1,glc[1879],string.format(glc[2286],M.name(GY.u.unit_id),HY,M.name(EY[GY.kind])))
else
j.log(1,glc[1879],string.format(glc[2287],M.name(GY.u.unit_id),HY,tostring(JY)))
end
