function bb.roomValue(fnb,gnb)
local hnb,inb=fnb.tags,fnb.d
local jnb=0
if hnb[bb.T.GOLD]then
jnb=jnb+12
end
if hnb[bb.T.CHEST]then
jnb=jnb+4
end
if hnb[bb.T.MONEY]then
jnb=jnb+(inb<=15 and 2 or 0.5)
end
if hnb[bb.T.SHOP]then
if inb>=10 and inb<=15 then
jnb=jnb+(gnb>=300 and 5 or 1)
else
jnb=jnb+(gnb>=300 and(inb>15 and 3 or 1)or 0.3)
end
end
if hnb[bb.T.SHRINE]then
jnb=jnb+1.5
end
if hnb[bb.T.CURSE]then
jnb=jnb-bb.curseCost(bb.roomCurse(fnb.r))
end
return jnb
end
