function bb.sim(Mnb,Nnb,Onb)
if not H.sim or type(Mnb.r._l)~=glc[1375]then
return nil
end
local Pnb=tostring(Mnb.r._r or(Mnb.d..glc[1485]..Mnb.choice))..(Nnb and(glc[2062]..tostring(Nnb))or glc[304])..(Onb and glc[2502]or glc[304])
local Qnb=bb.data()
local Rnb=bb.fx(Qnb,bb.roomCurse(Mnb.r),Nnb)
local Snb=N.teamSig()..glc[2503]..bb.fxText(Rnb)..(H.killZone~=false and glc[2504]or glc[304])
local Tnb=I.dg.sim[Pnb]
if Tnb and Tnb.sig==Snb then
return not Tnb.none and Tnb or nil
end
local Unb={}
for Vnb,Wnb in ipairs(M.equipped())do
table.insert(Unb,Wnb.u)
end
if#Unb==0 then
return nil
end
local Xnb=V.applyFx(V.info(V.slim(Mnb.r._l),glc[1680],nil,bb.mod(Mnb.r._l)),Rnb)
if Onb then
Xnb.zone=false
end
local Ynb=V.wave(Xnb,1,true)
if#Ynb==0 then
Tnb={none=true,sig=Snb,at=os.time()}
else
local Znb=V.evaluate(Xnb,V.teamFrom(Unb,Xnb.map))
Tnb={p=Znb.p,wave=Znb.wave,won=Znb.won,total=Xnb.total,margin=Znb.margin,sig=Snb,at=os.time()}
end
I.dg.sim[Pnb]=Tnb
if L.count(I.dg.sim)>60 then
local _nb,aob
for bob,cob in pairs(I.dg.sim)do
if not aob or(cob.at or 0)<aob then
_nb,aob=bob,cob.at or 0
end
end
I.dg.sim[_nb]=nil
end
j.saveSoon()
return not Tnb.none and Tnb or nil
end
function bb.winP(dob)
local eob=tostring(math.min(4,math.max(1,math.ceil(dob.d/5))))
local fob=I.dg.depth[eob]or{runs=0,wins=0}
local gob=L.clamp(0.95-0.015*dob.d,0.5,0.95)
local hob=((tonumber(fob.wins)or 0)+gob*2)/((tonumber(fob.runs)or 0)+2)
local iob,job=pcall(bb.sim,dob)
if iob and job and job.p then
hob=(hob*2+job.p)/3
end
return hob,iob and job or nil
end
function bb.hopeless(kob)
return kob~=nil and kob.won==false and(tonumber(kob.p)or 1)<=0.05
end
function bb.stake(lob)
local mob,nob,oob=bb.res(lob)
return nob+2*oob
end
function bb.curseBar(pob,qob)
local rob=bb.stake(pob)
if qob>=15 or rob>=8 then
return 0.9,glc[2505],rob
end
if qob>=10 or rob>=4 then
return 0.6,glc[2506],rob
end
return 0.1,glc[2507],rob
end
function bb.blindCurse(sob,tob)
return bb.fxText(bb.fx(sob,tob))==bb.fxText(bb.fx(sob))
end
function bb.curseOk(uob,vob,wob,xob,yob)
local zob=tostring((bb.item(uob)or{}).name or uob)
local Aob,Bob,Cob=bb.curseBar(vob,wob)
if Aob>0.2 and bb.blindCurse(vob,uob)then
return false,string.format(glc[2508],zob,Cob)
end
local function Dob(Eob)
return Eob==nil or(tonumber(Eob.p)or 1)>=Aob
end
if xob then
local Fob,Gob=pcall(bb.sim,xob,nil,true)
if Fob and not Dob(Gob)then
return false,string.format(glc[2509],zob,(Bob:gsub(glc[2510],glc[2511])),tostring(Gob.margin or glc[1588]))
end
end
if#yob==0 then
return true
end
local Hob
for Iob,Job in ipairs(yob)do
local Kob,Lob=pcall(bb.sim,Job,uob,true)
if not Kob or Dob(Lob)then
return true
end
if not Hob or(tonumber(Lob.p)or 0)>(tonumber(Hob.p)or 0)then
Hob=Lob
end
end
return false,string.format(glc[2512],zob,Bob,tostring(Hob and Hob.margin or glc[1588]))
end
function bb.curseGate(Mob,Nob)
local Oob=bb.roomCurse(Mob.r)
if not Oob then
return true
end
return bb.curseOk(Oob,Nob,Mob.d,Mob,bb.after(Nob,Mob.choice))
end
function bb.payValue()
local Pob,Qob=0,0
for Rob,Sob in ipairs(I.dg.pay or{})do
if type(Sob.items)==glc[1375]then
local Tob=tonumber(Sob.gems)or 0
for Uob,Vob in pairs(Sob.items)do
if(tonumber(Vob)or 0)>0 then
Tob=Tob+N.itemValue(Uob,Vob)
end
end
Pob,Qob=Pob+Tob,Qob+1
end
end
if Qob<5 then
return nil
end
return Pob/Qob*0.7
end
function bb.pick(Wob)
local Xob,Yob=bb.curses(Wob),bb.lives(Wob)
local Zob=bb.res(Wob)
local _ob=bb.rooms(Wob)
local apb={}
for bpb,cpb in ipairs(_ob)do
table.insert(apb,tostring(cpb.r._r))
end
local dpb=table.concat(apb,glc[1835])..string.format(glc[2513],Yob,Zob,Xob,N.teamSig())
if bb._pick and bb._pick.sig==dpb then
return bb._pick.x
end
local epb,fpb
for gpb,hpb in ipairs(_ob)do
local ipb=bb.roomValue(hpb,Zob)
local jpb,kpb
for lpb,mpb in ipairs(bb.after(Wob,hpb.choice))do
local npb=bb.roomValue(mpb,Zob)
if not jpb or npb>jpb then
jpb,kpb=npb,mpb
end
end
local opb,ppb=bb.winP(hpb)
local qpb=1-(1-opb)^math.max(1,Yob)
local rpb=Yob>=3 and 1 or(Yob==2 and 2 or 6)
hpb.p,hpb.sim,hpb.value,hpb.nextValue,hpb.nextRoom=opb,ppb,ipb,jpb or 0,kpb
hpb.score=qpb*(ipb+0.6*(jpb or 0))-(1-opb)*rpb
local spb,tpb,upb=pcall(bb.curseGate,hpb,Wob)
if spb and not tpb then
hpb.blocked=upb
end
if not hpb.blocked and(not epb or hpb.score>epb.score)then
epb=hpb
end
if not fpb or hpb.score>fpb.score then
fpb=hpb
end
end
epb=epb or fpb
bb._pick={sig=dpb,x=epb,rooms=_ob}
return epb
end
function bb.roomName(vpb)
