function bb.offers(Upb,Vpb)
local Wpb={}
if type(Upb)~=glc[1375]then
return Wpb
end
for Xpb,Ypb in pairs(Upb)do
local Zpb,_pb
if type(Ypb)==glc[1375]then
Zpb=Ypb.id or Ypb.item_id or Ypb.item
_pb=tonumber(Ypb.cost)or tonumber(Ypb.price)
elseif type(Ypb)==glc[1377]then
Zpb=Ypb
elseif bb.item(Xpb)then
Zpb=Xpb
_pb=tonumber(Ypb)
end
if type(Zpb)==glc[1377]and bb.item(Zpb)then
table.insert(Wpb,{key=Xpb,id=Zpb,cost=_pb or tonumber(bb.item(Zpb).cost)or 0,bought=type(Ypb)==glc[1375]and(Ypb.bought or Ypb.sold or Ypb.purchased)or nil})
end
end
if#Wpb==0 and not Vpb then
for aqb,bqb in pairs(Upb)do
if type(bqb)==glc[1375]then
Wpb=bb.offers(bqb,true)
if#Wpb>0 then
break
end
end
end
end
return Wpb
end
function bb.buy(cqb)
local dqb=bb.res(bb.data())
local eqb={}
if I.dg.buyArg==glc[2377]then
eqb={cqb.id,cqb.key}
else
eqb={cqb.key,cqb.id}
end
if eqb[1]==eqb[2]then
eqb[2]=nil
end
for fqb,gqb in ipairs(eqb)do
local hqb,iqb=j.request(glc[2523],glc[2524],gqb)
local jqb=L.now()
while L.now()-jqb<3 and bb.res(bb.data())>=dqb do
task.wait(0.25)
end
if bb.res(bb.data())<dqb then
I.dg.buyArg=(gqb==cqb.id and cqb.id~=cqb.key)and glc[2377]or glc[2525]
return true
end
if not hqb then
break
end
end
return false
end
function bb.shopAhead(kqb)
for lqb,mqb in ipairs(bb.rooms(kqb))do
if mqb.tags[bb.T.SHOP]then
return true
end
for nqb,oqb in ipairs(bb.after(kqb,mqb.choice))do
if oqb.tags[bb.T.SHOP]then
return true
end
end
end
return false
end
bb.LUCK_RESERVE=500
bb.MIN_WORTH=0.02
bb.TOP_WORTH=0.08
function bb.shop(pqb,qqb)
local rqb=bb.cleared(pqb)
local sqb=bb.res(pqb)
local tqb=1+0.1*(bb.items(pqb)._curse_shop or 0)
local uqb=bb.shopAhead(pqb)and math.ceil(bb.LUCK_RESERVE*tqb)or 0
local vqb={}
local wqb,xqb={},0
for yqb,zqb in ipairs(bb.offers(qqb and qqb.data))do
zqb.cost=math.ceil(zqb.cost*tqb)
table.insert(wqb,tostring(bb.item(zqb.id).name or zqb.id))
if not zqb.bought and not bb.isCurse(zqb.id)then
zqb.luck=tonumber(bb.item(zqb.id).luck_increase)~=nil
zqb.v=bb.itemValue(zqb.id,pqb)
if not zqb.luck and zqb.v/math.max(1,zqb.cost)<bb.MIN_WORTH then
xqb=xqb+1
elseif zqb.v>0 and(zqb.luck or rqb>=10 or zqb.v/math.max(1,zqb.cost)>=bb.TOP_WORTH)then
table.insert(vqb,zqb)
end
end
end
table.sort(vqb,function(Aqb,Bqb)
if Aqb.luck~=Bqb.luck then
return Aqb.luck
end
return Aqb.v/math.max(1,Aqb.cost)>Bqb.v/math.max(1,Bqb.cost)
end)
local Cqb,Dqb,Eqb={},0,0
for Fqb,Gqb in ipairs(vqb)do
if Gqb.cost<=sqb-(Gqb.luck and 0 or uqb)then
if bb.buy(Gqb)then
sqb=bb.res(bb.data())
table.insert(Cqb,string.format(glc[2526],tostring(bb.item(Gqb.id).name or Gqb.id),Gqb.cost))
end
elseif Gqb.cost<=sqb then
Eqb=Eqb+1
else
Dqb=Dqb+1
end
end
bb.note(string.format(glc[2527],rqb,#wqb>0 and table.concat(wqb,glc[1470])or glc[2528],#Cqb>0 and(glc[2529]..table.concat(Cqb,glc[1470]))or(rqb<10 and glc[2530]or(Eqb>0 and glc[2531]or glc[2532])),sqb,Dqb>0 and string.format(glc[2533],Dqb)or glc[304],Eqb>0 and string.format(glc[2534],Eqb,uqb)or glc[304],xqb>0 and string.format(glc[2535],xqb)or glc[304]))
j.request(glc[2536],glc[2537])
end
function bb.shrine(Hqb,Iqb)
local Jqb=bb.offers(Iqb and Iqb.data)
local Kqb,Lqb=0,{}
local Mqb
for Nqb,Oqb in ipairs(Jqb)do
local Pqb=bb.item(Oqb.id)
table.insert(Lqb,tostring(Pqb and Pqb.name or Oqb.id))
if bb.isCurse(Oqb.id)then
local Qqb,Rqb,Sqb=pcall(bb.curseOk,Oqb.id,Hqb,bb.cleared(Hqb)+1,nil,bb.rooms(Hqb))
if Qqb and not Rqb then
Mqb=Sqb
end
else
Kqb=Kqb+bb.itemValue(Oqb.id,Hqb)
end
end
local Tqb= #Jqb>0 and Kqb>0 and not Mqb
if Tqb then
j.request(glc[2538],glc[2539])
else
j.request(glc[2536],glc[2537])
end
bb.note(string.format(glc[2540],#Lqb>0 and table.concat(Lqb,glc[1470])or glc[2528],Tqb and glc[2541]or(Mqb and(glc[2542]..Mqb)or glc[2543])))
end
function bb.wallet()
local Uqb=G.session()and G.session().profile_data or{}
local Vqb=Uqb.inventory or{}
local Wqb={gems=tonumber(G.cur(glc[1435]))or 0,gold=tonumber(G.cur(glc[1437]))or 0,items={},units={},unique=0}
