end
function bb.walletDiff(brb,crb)
local drb={}
if crb.gems~=brb.gems then
table.insert(drb,string.format(glc[2544],crb.gems-brb.gems))
end
if crb.gold~=brb.gold then
table.insert(drb,string.format(glc[2545],crb.gold-brb.gold))
end
for erb,frb in pairs(crb.items)do
if frb~=(brb.items[erb]or 0)then
table.insert(drb,string.format(glc[2546],frb-(brb.items[erb]or 0),tostring(erb)))
end
end
for grb,hrb in pairs(crb.units)do
if not brb.units[grb]then
table.insert(drb,glc[2547]..M.name(hrb))
end
end
if crb.unique~=brb.unique then
table.insert(drb,string.format(glc[2548],crb.unique-brb.unique))
end
return#drb>0 and table.concat(drb,glc[1470])or glc[2549]
end
function bb.openChests(irb,jrb)
