function P.infWave(Yub)
P.infExtend()
if H.trainLeave and not P.stopping then
local Zub,_ub=pcall(P.trainLeave,Yub)
if not Zub then
j.log(1,glc[1905],glc[2626]..tostring(_ub))
end
end
if H.infiniteStop and not P.stopping then
local avb,bvb=pcall(P.infStop,Yub)
if not avb then
j.log(1,glc[1905],glc[2627]..tostring(bvb))
end
end
local cvb=N.infTier(Yub-1)
if cvb<=0 or cvb==P.infTierSeen then
return
end
P.infTierSeen=cvb
task.delay(5,function()
if not j.alive then
return
end
local dvb=G.prof()
local evb=dvb and dvb.daily_infinite_reward_claims and dvb.daily_infinite_reward_claims[P.ld.id]
local fvb=type(evb)==glc[1375]and(tonumber(evb.highest_claimed_wave)or 0)>=cvb and os.time()-(tonumber(evb.highest_claim_time)or 0)<900
if fvb then
I.infLive=true
end
j.log(1,glc[2628],string.format(glc[2629],cvb,fvb and glc[2630]or glc[2631]))
end)
end
function P.infStop(gvb)
local hvb=0
for ivb,jvb in ipairs(L.list(G.GS.DAILY_INFINITE_REWARDS))do
hvb=math.max(hvb,tonumber(jvb.wave)or 0)
end
if hvb<=0 or gvb<=hvb+1 then
return
end
local kvb=I.train.on
if P.trainee and kvb and kvb.have+(kvb.got or 0)+(P.trainTk or 0)<kvb.need then
return
end
if not O.every(glc[2632],60)then
return
end
local lvb=N.rec(P.key)
local mvb=tonumber(lvb.timed)or 0
local nvb=(mvb>0 and(lvb.sec or 0)>0)and math.max(0.5,((lvb.gems or 0)-200*mvb)/(lvb.sec/60))or 2.5
local ovb=pcall(N.pick)
local pvb
for qvb,rvb in ipairs(ovb and N.lastScored or{})do
if rvb.kind~=glc[1394]and(not pvb or(rvb.score or 0)>(pvb.score or 0))then
pvb=rvb
end
end
if not pvb or(pvb.score or 0)<=nvb then
return
end
P.stopping=true
j.log(1,glc[2628],string.format(glc[2633],gvb,nvb,pvb.score,pvb.label))
P.sellAll()
end
function P.trainLeave(svb)
local tvb=I.train.on
if not(P.infinite and P.trainee and tvb)then
return
end
P.trainCount()
local uvb=tvb.have+(tvb.got or 0)+(P.trainTk or 0)
if uvb<tvb.need then
return
end
local vvb,wvb,xvb=pcall(N.infDaily,G.prof(),P.ld.id,(N.infReach(P.key)))
if vvb and(wvb or 0)>0 and xvb>0 and svb<=xvb then
j.status(glc[2082],string.format(glc[2634],M.name(tvb.id),tvb.what,xvb))
return
end
P.stopping=true
j.log(1,glc[2628],string.format(glc[2635],M.name(tvb.id),tvb.what,L.fmt(uvb),L.fmt(tvb.need),svb))
