local Axb=zxb._stats
if not M.isFarm(Axb.id.Value)and Axb:FindFirstChild(glc[1511])then
table.insert(xxb,{p=L.flat(zxb:GetPivot().Position),r=Axb.range.Value*(M.SUMMONER[Axb.id.Value]and M.SUMMONER[Axb.id.Value].reach or 1),air=P.canAir(zxb)})
