end
local CHb=P.money()
local DHb,EHb=j.request(glc[2709],glc[2710],xHb.uuid,G.Util.CFramePLV(AHb,P.lookAt(AHb)))
if DHb and EHb then
P.spent=P.spent+(xHb.data.cost or 0)
