j.log(1,glc[2703],string.format(glc[2712],M.name(xHb.id),P.spotKey(AHb),BHb,yHb))
P.placeLog=P.placeLog or{}
table.insert(P.placeLog,{t=math.floor(L.now()-(P.startT or L.now())),w=P.wave(),id=xHb.id,x=math.floor(AHb.X),z=math.floor(AHb.Z),cover=math.floor((BHb or 0)+0.5),why=tostring(yHb):sub(1,90)})
