if P.placeFail[xHb.uuid]>=2 then
P.noSpot[xHb.uuid]=3
j.log(1,glc[2703],string.format(glc[2714],M.name(xHb.id),P.fieldCount(),P.FIELD_MAX))
end
end
if DHb and CHb>=(xHb.data.cost or 0)and not P.random then
local FHb=P.spotKey(AHb)
P.refused[FHb]=true
local GHb=P.mapKey()
I.blocked[GHb]=I.blocked[GHb]or{}
if not P.refusedRun[FHb]then
