hIb=hIb+jIb.y
end
local kIb=math.min(30,RHb-(P.startT or RHb))
P.incomeRate=kIb>=8 and hIb/kIb or nil
for lIb,mIb in ipairs(P.enemies)do
local nIb=mIb.m
local oIb=P.track[nIb]
