if rSb then
jSb[pSb]=jSb[pSb]+rSb.dot*oSb.damage.Value
end
kSb=kSb+qSb
end
end
for sSb,tSb in pairs(jSb)do
lSb=lSb+tSb
end
if kSb<=0 or lSb<=0 then
return
end
P.lastEff={}
for uSb,vSb in pairs(iSb)do
local wSb,xSb=vSb/kSb,jSb[uSb]/lSb
if xSb>0.02 then
local ySb=I.learn[uSb]or{eff=1,n=0}
local zSb=math.max(0.02,0.25*math.sqrt(30/(30+ySb.n)))
local ASb=L.clamp(wSb/xSb,0.3,3)
P.lastEff[uSb]=math.floor(ASb*1000+0.5)/1000
ySb.eff=ySb.eff+(ASb-ySb.eff)*zSb
ySb.n=ySb.n+1
I.learn[uSb]=ySb
end
end
end
